#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

// Read the sample CSV file
const csvPath = '/data/samples/user_activity_sample.csv';
const csvContent = fs.readFileSync(csvPath, 'utf8');

// Parse CSV (simple parsing for this example)
const lines = csvContent.trim().split('\n');
const headers = lines[0].split(',');
const dataLines = lines.slice(1);

console.log('Converting CSV data to JSON for Moose UserActivity model...\n');

// Convert CSV to JSON objects matching our UserActivity interface
const jsonData = dataLines.map(line => {
  const values = line.split(',');
  const eventId = values[0];
  const eventTs = values[1];
  const userId = values[2];
  const action = values[3];
  const durationMs = parseFloat(values[4]) || 0; // Default nullable duration to 0

  return {
    eventId,
    eventTs,
    userId,
    action,
    durationMs
  };
});

// Output the JSON data
console.log('Sample JSON data for ingestion:');
jsonData.slice(0, 3).forEach((record, i) => {
  console.log(`${i + 1}. ${JSON.stringify(record)}`);
});

console.log(`\n... and ${jsonData.length - 3} more records\n`);

// Generate curl commands for ingestion
console.log('Ingestion commands (would be used with running Moose server):');
jsonData.slice(0, 2).forEach((record, i) => {
  console.log(`curl -X POST http://localhost:4000/ingest/UserActivity \\
  -H "Content-Type: application/json" \\
  -d '${JSON.stringify(record)}'`);
  if (i === 0) console.log('');
});

// Save all data as JSON for potential batch loading
fs.writeFileSync('/workspace/moose-project/user_activity_data.json', JSON.stringify(jsonData, null, 2));
console.log(`\nAll ${jsonData.length} records saved to user_activity_data.json`);

console.log('\nData model optimizations applied:');
console.log('- ORDER BY (userId, eventTs, action) for efficient user-based and action-based queries');
console.log('- Nullable durationMs values default to 0');
console.log('- Optimized for query patterns:');
console.log('  1. Activity counts per user over date range');
console.log('  2. Total duration per action type');

